//! Block-state tables, one per protocol (`blocks_<protocol>.rs`, generated by `tools/gen_blocks.py`),
//! and lookups by state id.
//!
//! A block owns the state ids `first .. first + product(value counts)`. A state's properties are the
//! mixed-radix digits of `state - first`: properties sorted by name, the last one varying fastest,
//! each property's values in vanilla's order. The generator checked this against every state id
//! of the vanilla reports.

/// The block states of one protocol version.
pub struct Table {
    /// Number of block states: ids are `0..states`.
    pub states: u32,
    /// Distinct property definitions: name and values in id order.
    pub props: &'static [(&'static str, &'static [&'static str])],
    /// Blocks in state-id order: name (no namespace), first state id, and the indices into
    /// [`Table::props`] of its properties, sorted by property name.
    pub blocks: &'static [(&'static str, u32, &'static [u8])],
}

impl Table {
    /// The table of `protocol`; unknown protocols get the newest one.
    pub fn for_protocol(protocol: i32) -> &'static Table {
        match protocol {
            776 => &super::blocks_776::TABLE,
            775 => &super::blocks_775::TABLE,
            774 => &super::blocks_774::TABLE,
            _ => &super::blocks_777::TABLE,
        }
    }

    /// Bits per entry of the global (direct) palette: `ceil(log2(states))`, as vanilla's
    /// `Mth.ceillog2(Block.BLOCK_STATE_REGISTRY.size())`.
    pub fn global_bits(&self) -> u32 {
        ceil_log2(self.states)
    }

    /// Index into [`Table::blocks`] of the block owning `state`.
    pub fn block_index(&self, state: u32) -> Option<usize> {
        if state >= self.states {
            return None;
        }
        Some(self.blocks.partition_point(|b| b.1 <= state) - 1)
    }

    pub fn name(&self, state: u32) -> Option<&'static str> {
        self.block_index(state).map(|i| self.blocks[i].0)
    }

    /// `(property, value)` pairs of `state`, properties sorted by name; empty for an unknown id.
    pub fn properties(&self, state: u32) -> Vec<(&'static str, &'static str)> {
        let mut out = Vec::new();
        self.each_property(state, |name, value| {
            out.push((name, value));
            false
        });
        out.reverse();
        out
    }

    /// The value of one property of `state`, if its block has it.
    pub fn property(&self, state: u32, name: &str) -> Option<&'static str> {
        let mut found = None;
        self.each_property(state, |n, v| {
            if n == name {
                found = Some(v);
            }
            found.is_some()
        });
        found
    }

    /// Calls `f(name, value)` for the properties of `state`, LAST property first, until it
    /// returns true.
    fn each_property(&self, state: u32, mut f: impl FnMut(&'static str, &'static str) -> bool) {
        let Some(i) = self.block_index(state) else { return };
        let (_, first, props) = self.blocks[i];
        let mut rest = state - first;
        for &p in props.iter().rev() {
            let (name, values) = self.props[p as usize];
            let n = values.len() as u32;
            if f(name, values[(rest % n) as usize]) {
                return;
            }
            rest /= n;
        }
    }
}

/// Smallest `k` with `2^k >= n` (vanilla's `Mth.ceillog2`); 0 for `n <= 1`.
pub fn ceil_log2(n: u32) -> u32 {
    if n <= 1 { 0 } else { u32::BITS - (n - 1).leading_zeros() }
}
